-- Help join requests
--
-- One-time content move: joining an organization by ID now sends a request the owner approves (migration
-- 20261024200000_organization_join_requests), so the pages that said it joins straight away are corrected. Changes only
-- the wrong sentences: workspace/organizations (joining-an-organization rewritten for the request flow, organization-menu,
-- organization-settings), workspace/members (description, roles, removing-a-member, and a new requests-to-join section),
-- quickstart (joining-your-teams-organization), core-concepts (members-and-roles), welcome (how-it-fits text and its
-- Members feature) and workspace/profile (your-organizations). Anchors and section titles are unchanged.
-- Written from a survey of C:\Pro\geiger-dash (app/org/organizations-client.jsx (JoinForm, MembersTab,
-- PendingJoinRequests, OrganizationCard), app/org/actions.js, app/org/page.js, app/onboarding/onboarding-wizard.jsx,
-- app/onboarding/actions.js, app/onboarding/page.js, lib/org/join-requests.js, lib/notifications/types.js,
-- lib/notifications/send.js, supabase/migrations/20261024200000_organization_join_requests.sql).
-- Built on live snapshots (every page last written by its 2026-10-24 help migration, none edited in Studio); @down
-- restores those snapshots exactly. Push it with, or right after, the Dash deploy that ships the request flow.
-- Later edits happen in Studio, so this must never re-run.

-- @up
update public.docs_content_blocks
set content = $html$<p>To join an organization, you ask to join with its ID and its owner approves the request. You need the ID from someone who already belongs to it. They copy it with <strong>Copy ID</strong> in the organization's <strong>⋯</strong> menu.</p><ol><li>On the <a href="/org">Organizations page</a>, choose the person-and-plus icon next to <strong>Create</strong>.</li><li>In the <strong>Join organization</strong> dialog, paste the ID into <strong>Organization ID</strong>.</li><li>Optional: write a <strong>Note for the owner</strong>, up to 500 characters. The owner sees it with your request.</li><li>Choose <strong>Request to join</strong>.</li></ol><p>Dash shows <strong>Request sent to</strong> with the organization's name, and the organization appears under <strong>Requests to join</strong> at the top of the Organizations page, marked Pending approval. You aren't a member yet. The owner and any members with the Manager role get a notification, and the owner approves or declines the request on the <strong>Members</strong> tab of <strong>Organization Settings</strong> (see <a href="/help/workspace/members#requests-to-join">Approving requests to join</a>).</p><p>You get a notification when the owner decides. Once they approve, you're a member with the User role and the organization's card appears in your list. If the ID doesn't match an organization, Dash shows <strong>No organization found for that ID or URL.</strong> Asking again while a request is pending doesn't send a second one. To bring someone in with a different role, or without a request, the owner invites them by email instead: see <a href="/help/workspace/members#inviting-members">Members and roles</a>.</p>$html$
where anchor_id = 'joining-an-organization'
  and page_id in (select id from public.docs_pages where slug = 'workspace/organizations' and deleted_at is null);

update public.docs_content_blocks
set content = $html$<p>Each organization card has a <strong>⋯</strong> menu at its top right, and right-clicking the card opens the same items. Everyone sees <strong>Open</strong> and <strong>Copy ID</strong>; only the organization's owner sees <strong>Settings</strong> and <strong>Usage</strong>.</p><ul><li><strong>Open</strong>: opens the organization's page and its projects.</li><li><strong>Settings</strong>: opens <strong>Organization Settings</strong>.</li><li><strong>Usage</strong>: opens the organization's Usage page. See <a href="/help/workspace/billing#usage-page">Billing and usage</a>.</li><li><strong>Copy ID</strong>: copies the organization's ID, and Dash shows <strong>ID copied.</strong></li></ul><p>The ID is what someone pastes into <strong>Join organization</strong> to ask to join. They become a member, with the User role, only once the owner approves their request. To choose someone's role yourself, invite them by email instead (see <a href="/help/workspace/members#inviting-members">Members and roles</a>).</p>$html$
where anchor_id = 'organization-menu'
  and page_id in (select id from public.docs_pages where slug = 'workspace/organizations' and deleted_at is null);

update public.docs_content_blocks
set content = $html$<p>To open an organization's settings, choose <strong>Settings</strong> in its card's <strong>⋯</strong> menu. Only the organization's owner sees it. <strong>Organization Settings</strong> opens on the <strong>General</strong> tab.</p><ul><li><strong>General</strong>: the organization's icon. See <a href="/help/workspace/organizations#organization-icon">Changing the organization icon</a>.</li><li><strong>Members</strong>: invite people by email, approve requests to join, change their roles and remove them. See <a href="/help/workspace/members">Members and roles</a>.</li><li><strong>Domain</strong>: the organization's own subdomain. It appears only while the organization has the Custom Subdomain add-on. See <a href="/help/workspace/add-ons#custom-subdomain">Add-ons</a>.</li><li><strong>Emails</strong>: the organization's email templates. It appears only while the organization has the Custom Email Templates add-on. See <a href="/help/workspace/add-ons#email-templates">Add-ons</a>.</li><li><strong>OAuth</strong>: the organization's own sign-in provider. It appears only while the organization has the OAuth / SSO Login add-on. See <a href="/help/workspace/sign-in#setting-up-sso">Sign-in and OAuth</a>.</li></ul><p>Each tab saves its own changes (the icon as soon as you upload it), so closing the dialog doesn't undo them.</p>$html$
where anchor_id = 'organization-settings'
  and page_id in (select id from public.docs_pages where slug = 'workspace/organizations' and deleted_at is null);

update public.docs_pages
set description = 'Invite people to your organization by email, approve requests to join, accept invites and set each member''s role. Revoke pending invites or remove members.'
where slug = 'workspace/members' and deleted_at is null;

update public.docs_content_blocks
set content = $html$<p>Every member of an organization has a role: Manager, User, Leader, Technical Officer or Financial Officer. You choose it when you invite someone, and new invites are User. People whose request to join with the <a href="/help/workspace/organizations#joining-an-organization">organization ID</a> is approved, and people who join through the organization's <a href="/help/workspace/sign-in#signing-in-with-sso">SSO sign-in</a>, also start as User.</p><p>The organization's owner, the person who created it, is listed as Owner. That role is fixed, and the owner can't be removed from the organization.</p><p>In Dash, a member's role doesn't change what they can do. Only the owner can open <strong>Organization Settings</strong>, so only the owner invites people, approves requests to join, changes roles and removes members. Every member, whatever their role, can open the organization and work in its <a href="/help/workspace/projects">projects</a>.</p><p>Some apps read the role when a member works in a project. In Events, Assets, Campaign, Grey and Pods, a Manager starts with the app's manager role, and every other role starts as an ordinary member. Each app decides what its roles allow. The other apps don't use the organization role.</p>$html$
where anchor_id = 'roles'
  and page_id in (select id from public.docs_pages where slug = 'workspace/members' and deleted_at is null);

update public.docs_content_blocks
set content = $html$<p>To remove someone from an organization, open the <strong>Members</strong> tab in <strong>Organization Settings</strong>, open the <strong>⋯</strong> menu beside their name and choose <strong>Remove from workspace</strong>. Dash asks you to confirm first: choose <strong>Remove</strong> in the dialog. Only the owner can remove members, and the owner can't be removed.</p><p>A removed member loses access to the organization and all of its projects straight away. What they made in those projects stays where it is.</p><p>Removing someone doesn't stop them from coming back. A new invite adds them again, and so does signing in through the organization's SSO, if it has one. They can also ask to join again with the organization ID, and you decide whether to approve it (see <a href="/help/workspace/members#requests-to-join">Approving requests to join</a>).</p><p>There's no way to leave an organization yourself. To leave, ask its owner to remove you.</p>$html$
where anchor_id = 'removing-a-member'
  and page_id in (select id from public.docs_pages where slug = 'workspace/members' and deleted_at is null);

insert into public.docs_content_blocks (page_id, anchor_id, eyebrow, title, content, sort_order)
select p.id, 'requests-to-join', 'Requests', 'Approving requests to join', $html$<p>To approve someone who asked to join your organization with its ID, open the <strong>Members</strong> tab in <strong>Organization Settings</strong> and look under <strong>Requests to join</strong>. Only the organization's owner can open it. The section appears only while there's at least one request, oldest first, and each one shows the person's name, email and note, if they wrote one.</p><ul><li><strong>Approve</strong>: adds the person to the organization with the User role. Dash shows <strong>Request approved.</strong> and they appear under <strong>Members</strong>, where you can change their role.</li><li><strong>Decline</strong>: turns the request down without adding them. Dash shows <strong>Request declined.</strong></li></ul><p>Both take effect straight away, without asking first, and the person gets a notification either way. Someone you decline can ask again with the organization ID. When a request arrives, the owner and any members with the Manager role get a notification, and its <strong>Review</strong> button opens the <strong>Members</strong> tab for the owner.</p>$html$, 45
from public.docs_pages p
where p.slug = 'workspace/members' and p.deleted_at is null
on conflict (page_id, anchor_id) do nothing;

update public.docs_content_blocks
set content = $html$<p>To join an organization your team already uses, accept the invitation email if someone sent you one: see <a href="/help/workspace/members#accepting-an-invite">Accepting an invite</a>. Otherwise, ask a member for the organization's ID and ask to join with it. They copy it with <strong>Copy ID</strong> in the organization card's <strong>⋯</strong> menu. Then, in the setup wizard:</p><ol><li>Choose <strong>Join an existing organization</strong>, then <strong>Continue</strong>.</li><li>Paste the ID under <strong>Organization ID or URL</strong> and choose <strong>Find organization</strong>.</li><li>Check the organization's name and member count. Optional: write a <strong>Note for the owner</strong>.</li><li>Choose <strong>Request to join</strong> followed by its name.</li></ol><p>The wizard shows <strong>Request sent</strong>. You join with the User role once the organization's owner approves the request, and you get a notification when they approve or decline it. Until then, Dash opens the wizard on your request: choose <strong>Check status</strong> to look again, and once it's approved Dash opens the Organizations page. Your organization's plan and projects are already in place, so you can go on to <a href="/help/quickstart#opening-a-project-in-an-app">opening a project in an app</a>.</p>$html$
where anchor_id = 'joining-your-teams-organization'
  and page_id in (select id from public.docs_pages where slug = 'quickstart' and deleted_at is null);

update public.docs_content_blocks
set content = $html$<p>A member is a person in an organization. People join when they accept an email invite from the owner, when the owner approves their request to join with the organization's ID, or when they sign in through the organization's SSO. Every member sees all of the organization's projects, can create, edit and delete them, and can buy or upgrade the organization's plan.</p><p>Each member also has a role: Manager, User, Leader, Technical Officer or Financial Officer. In Dash, the role doesn't change what a member can do, but some apps read it to set a member's starting role in a project. The owner's role is fixed. The <a href="/help/workspace/members">Members and roles</a> guide covers invites, roles and removing members.</p>$html$
where anchor_id = 'members-and-roles'
  and page_id in (select id from public.docs_pages where slug = 'core-concepts' and deleted_at is null);

update public.docs_content_blocks
set content = $html$<p>Everything in Geiger starts with an <strong>organization</strong>. It holds your members, your projects, your plan and your add-ons, and its owner manages its settings. See <a href="/help/workspace/organizations">Organizations</a>.</p><p><strong>Members</strong> are the people in an organization. They join through an email invite, an approved request with the organization's ID, or its SSO sign-in, and each one has a role. See <a href="/help/workspace/members">Members and roles</a>.</p><p>A <strong>project</strong> is the shared home for a piece of work. You create it in Dash and choose the apps it uses, so one project can keep its plans in Flow and its files in Assets. See <a href="/help/workspace/projects">Projects</a>.</p><p>The organization's <strong>plan</strong> decides which apps its projects can use and how many projects it can have. <a href="/help/core-concepts">Core concepts</a> explains how the pieces relate.</p>$html$
where anchor_id = 'how-it-fits'
  and page_id in (select id from public.docs_pages where slug = 'welcome' and deleted_at is null);

update public.docs_content_blocks
set features = '[{"icon":"Building2","text":"Organization: members, projects, plan and add-ons"},{"icon":"Users","text":"Members: join by invite, approved request or SSO, each with a role"},{"icon":"FolderKanban","text":"Projects: one home for the work, opened in its apps"},{"icon":"CreditCard","text":"Plan: which apps and how many projects"}]'::jsonb
where anchor_id = 'how-it-fits'
  and page_id in (select id from public.docs_pages where slug = 'welcome' and deleted_at is null);

update public.docs_content_blocks
set content = $html$<p>The <strong>Organizations</strong> tab of your profile lists every organization you belong to, newest first, with the count beside the tab's name. Each row shows the organization's name, how many members it has and when it was created. Its badge says <strong>Owner</strong> or <strong>Creator</strong> (with a crown) when you own or created the organization, and <strong>Member</strong> otherwise. The badge doesn't show your <a href="/help/workspace/members#roles">role</a> inside the organization.</p><ul><li><strong>Open</strong> opens the organization's projects.</li><li>The gauge icon opens its <a href="/help/workspace/billing#usage-page">usage page</a>.</li><li>The copy icon copies its Organization ID, which other people use to <a href="/help/workspace/organizations#joining-an-organization">ask to join the organization</a>.</li></ul><p><strong>New Organization</strong> opens the Organizations page, where you <a href="/help/workspace/organizations#creating-an-organization">create an organization</a>. Until you belong to one, the tab shows <strong>Go to Organizations</strong> instead of a list.</p><p>When an organization has invited you, <strong>Pending Invitations</strong> sits at the top of the tab, with the role you're invited as and <strong>Accept</strong>. See <a href="/help/workspace/members#accepting-an-invite">accepting an invite</a>.</p>$html$
where anchor_id = 'your-organizations'
  and page_id in (select id from public.docs_pages where slug = 'workspace/profile' and deleted_at is null);

